#include "stdlib/math/base/special/betaincinv.h"
#include "stdlib/math/base/special/kernel_betaincinv.h"
#include "stdlib/math/base/assert/is_nan.h"
#include <stdbool.h>

/**
* Inverts the regularized incomplete beta function.
*
* @param p       probability value
* @param a       function parameter
* @param b       function parameter
* @param upper   boolean indicating whether to invert the upper tail
* @return        function value
*
* @example
* double y = stdlib_base_betaincinv( 0.2, 3.0, 3.0, false );
* // returns ~0.327
*/
double stdlib_base_betaincinv( const double p, const double a, const double b, const bool upper ) {
	double out1;
	double out2;

	if (
		stdlib_base_is_nan( p ) ||
		stdlib_base_is_nan( a ) ||
		stdlib_base_is_nan( b )
	) {
		return 0.0 / 0.0; // NaN
	}
	if ( a <= 0.0 || b <= 0.0 ) {
		return 0.0 / 0.0; // NaN
	}
	if ( p < 0.0 || p > 1.0 ) {
		return 0.0 / 0.0; // NaN
	}
	if ( upper ) {
		stdlib_base_kernel_betaincinv( a, b, 1.0 - p, p, &out1, &out2 );
	} else {
		stdlib_base_kernel_betaincinv( a, b, p, 1.0 - p, &out1, &out2 );
	}
	return out1;
}
